INSERT INTO `full_text` VALUES (13339,'RenderJS renderjs.js 001 /* * js_channel is a very lightweight abstraction on top of * postMessage which\ndefines message formats and semantics * to support interactions more rich than\njust message passing * js_channel supports: * + query/response - traditional\nrpc * + query/update/response - incremental async return of results * to a\nquery * + notifications - fire and forget * + error handling * * js_channel is\nbased heavily on json-rpc, but is focused at the * problem of inter-iframe RPC.\n* * Message types: * There are 5 types of messages that can flow over this\nchannel, * and you may determine what type of message an object is by *\nexamining its parameters: * 1. Requests * + integer id * + string method * +\n(optional) any params * 2. Callback Invocations (or just \"Callbacks\") * +\ninteger id * + string callback * + (optional) params * 3. Error Responses (or\njust \"Errors) * + integer id * + string error * + (optional) string message *\n4. Responses * + integer id * + (optional) any result * 5. Notifications * +\nstring method * + (optional) any params */ ;var Channel = (function() { \"use\nstrict\"; // current transaction id, start out at a random *odd* number between\n1 and a million // There is one current transaction counter id per page, and\nit\'s shared between // channel instances. That means of all messages posted\nfrom a single javascript // evaluation context, we\'ll never have two with the\nsame id. var s_curTranId = Math.floor(Math.random()*1000001); // no two bound\nchannels in the same javascript evaluation context may have the same origin,\nscope, and window. // futher if two bound channels have the same window and\nscope, they may not have *overlapping* origins // (either one or both support\n\'*\'). This restriction allows a single onMessage handler to efficiently //\nroute messages based on origin and scope. The s_boundChans maps origins to\nscopes, to message // handlers. Request and Notification messages are routed\nusing this table. // Finally, channels are inserted into this table when built,\nand removed when destroyed. var s_boundChans = { }; // add a channel to\ns_boundChans, throwing if a dup exists function s_addBoundChan(win, origin,\nscope, handler) { function hasWin(arr) { for (var i = 0; i < arr.length; i++)\nif (arr[i].win === win) return true; return false; } // does she exist? var\nexists = false; if (origin === \'*\') { // we must check all other origins,\nsadly. for (var k in s_boundChans) { if (!s_boundChans.hasOwnProperty(k))\ncontinue; if (k === \'*\') continue; if (typeof s_boundChans[k][scope] ===\n\'object\') { exists = hasWin(s_boundChans[k][scope]); if (exists) break; } } }\nelse { // we must check only \'*\' if ((s_boundChans[\'*\'] && s_boundChans[\'*\']\n[scope])) { exists = hasWin(s_boundChans[\'*\'][scope]); } if (!exists &&\ns_boundChans[origin] && s_boundChans[origin][scope]) { exists = hasWin\n(s_boundChans[origin][scope]); } } if (exists) throw \"A channel is already\nbound to the same window which overlaps with origin \'\"+ origin +\"\' and has\nscope \'\"+scope+\"\'\"; if (typeof s_boundChans[origin] != \'object\') s_boundChans\n[origin] = { }; if (typeof s_boundChans[origin][scope] != \'object\')\ns_boundChans[origin][scope] = [ ]; s_boundChans[origin][scope].push({win: win,\nhandler: handler}); } function s_removeBoundChan(win, origin, scope) { var arr\n= s_boundChans[origin][scope]; for (var i = 0; i < arr.length; i++) { if (arr\n[i].win === win) { arr.splice(i,1); } } if (s_boundChans[origin][scope].length\n=== 0) { delete s_boundChans[origin][scope]; } } function s_isArray(obj) { if\n(Array.isArray) return Array.isArray(obj); else { return\n(obj.constructor.toString().indexOf(\"Array\") != -1); } } // No two outstanding\noutbound messages may have the same id, period. Given that, a single table //\nmapping \"transaction ids\" to message handlers, allows efficient routing of\nCallback, Error, and // Response messages. Entries are added to this table when\nrequests are sent, and removed when // responses are received. var s_transIds =\n{ }; // class singleton onMessage handler // this function is registered once\nand all incoming messages route through here. This // arrangement allows\ncertain efficiencies, message data is only parsed once and dispatch // is more\nefficient, especially for large numbers of simultaneous channels. var\ns_onMessage = function(e) { try { var m = JSON.parse(e.data); if (typeof m !==\n\'object\' || m === null) throw \"malformed\"; } catch(e) { // just ignore any\nposted messages that do not consist of valid JSON return; } var w = e.source;\nvar o = e.origin; var s, i, meth; if (typeof m.method === \'string\') { var ar =\nm.method.split(\'::\'); if (ar.length == 2) { s = ar[0]; meth = ar[1]; } else {\nmeth = m.method; } } if (typeof m.id !== \'undefined\') i = m.id; // w is message\nsource window // o is message origin // m is parsed message // s is message\nscope // i is message id (or undefined) // meth is unscoped method name // ^^\nbased on these factors we can route the message // if it has a method it\'s\neither a notification or a request, // route using s_boundChans if (typeof meth\n=== \'string\') { var delivered = false; if (s_boundChans[o] && s_boundChans[o]\n[s]) { for (var j = 0; j < s_boundChans[o][s].length; j++) { if (s_boundChans\n[o][s][j].win === w) { s_boundChans[o][s][j].handler(o, meth, m); delivered =\ntrue; break; } } } if (!delivered && s_boundChans[\'*\'] && s_boundChans[\'*\'][s])\n{ for (var j = 0; j < s_boundChans[\'*\'][s].length; j++) { if (s_boundChans[\'*\']\n[s][j].win === w) { s_boundChans[\'*\'][s][j].handler(o, meth, m); break; } } } }\n// otherwise it must have an id (or be poorly formed else if (typeof i !=\n\'undefined\') { if (s_transIds[i]) s_transIds[i](o, meth, m); } }; // Setup\npostMessage event listeners if (window.addEventListener)\nwindow.addEventListener(\'message\', s_onMessage, false); else if\n(window.attachEvent) window.attachEvent(\'onmessage\', s_onMessage); /* a\nmessaging channel is constructed from a window and an origin. * the channel\nwill assert that all messages received over the * channel match the origin * *\nArguments to Channel.build(cfg): * * cfg.window - the remote window with which\nwe\'ll communicate * cfg.origin - the expected origin of the remote window, may\nbe \'*\' * which matches any origin * cfg.scope - the \'scope\' of messages. a\nscope string that is * prepended to message names. local and remote endpoints *\nof a single channel must agree upon scope. Scope may * not contain double\ncolons (\'::\'). * cfg.debugOutput - A boolean value. If true and\nwindow.console.log is * a function, then debug strings will be emitted to that\n* function. * cfg.debugOutput - A boolean value. If true and window.console.log\nis * a function, then debug strings will be emitted to that * function. *\ncfg.postMessageObserver - A function that will be passed two arguments, * an\norigin and a message. It will be passed these immediately * before messages are\nposted. * cfg.gotMessageObserver - A function that will be passed two\narguments, * an origin and a message. It will be passed these arguments *\nimmediately after they pass scope and origin checks, but before * they are\nprocessed. * cfg.onReady - A function that will be invoked when a channel\nbecomes \"ready\", * this occurs once both sides of the channel have been *\ninstantiated and an application level handshake is exchanged. * the onReady\nfunction will be passed a single argument which is * the channel object that\nwas returned from build(). */ return { build: function(cfg) { var debug =\nfunction(m) { if (cfg.debugOutput && window.console && window.console.log) { //\ntry to stringify, if it doesn\'t work we\'ll let javascript\'s built in toString\ndo its magic try { if (typeof m !== \'string\') m = JSON.stringify(m); } catch(e)\n{ } console.log(\"[\"+chanId+\"] \" + m); } }; /* browser capabilities check */ if\n(!window.postMessage) throw(\"jschannel cannot run this browser, no\npostMessage\"); if (!window.JSON || !window.JSON.stringify || !\nwindow.JSON.parse) { throw(\"jschannel cannot run this browser, no JSON parsing/\nserialization\"); } /* basic argument validation */ if (typeof cfg != \'object\')\nthrow(\"Channel build invoked without a proper object argument\"); if (!\ncfg.window || !cfg.window.postMessage) throw(\"Channel.build() called without a\nvalid window argument\"); /* we\'d have to do a little more work to be able to\nrun multiple channels that intercommunicate the same * window... Not sure if we\ncare to support that */ if (window === cfg.window) throw(\"target window is same\nas present window -- not allowed\"); // let\'s require that the client specify an\norigin. if we just assume \'*\' we\'ll be // propagating unsafe practices. that\nwould be lame. var validOrigin = false; if (typeof cfg.origin === \'string\') {\nvar oMatch; if (cfg.origin === \"*\") validOrigin = true; // allow valid domains\nunder http and https. Also, trim paths off otherwise valid origins. else if\n(null !== (oMatch = cfg.origin.match(/^https?:\\/\\/(?:[-a-zA-Z0-9_\\.])+(?::\\d+)?\n/))) { cfg.origin = oMatch[0].toLowerCase(); validOrigin = true; } } if (!\nvalidOrigin) throw (\"Channel.build() called with an invalid origin\"); if\n(typeof cfg.scope !== \'undefined\') { if (typeof cfg.scope !== \'string\') throw\n\'scope, when specified, must be a string\'; if (cfg.scope.split(\'::\').length >\n1) throw \"scope may not contain double colons: \'::\'\"; } /* private variables */\n// generate a random and psuedo unique id for this channel var chanId =\n(function () { var text = \"\"; var alpha =\n\"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\"; for(var i=0;\ni < 5; i++) text += alpha.charAt(Math.floor(Math.random() * alpha.length));\nreturn text; })(); // registrations: mapping method names to call objects var\nregTbl = { }; // current oustanding sent requests var outTbl = { }; // current\noustanding received requests var inTbl = { }; // are we ready yet? when false\nwe will block outbound messages. var ready = false; var pendingQueue = [ ]; var\ncreateTransaction = function(id,origin,callbacks) { var shouldDelayReturn =\nfalse; var completed = false; return { origin: origin, invoke: function(cbName,\nv) { // verify in table if (!inTbl[id]) throw \"attempting to invoke a callback\nof a nonexistent transaction: \" + id; // verify that the callback name is valid\nvar valid = false; for (var i = 0; i < callbacks.length; i++) if (cbName ===\ncallbacks[i]) { valid = true; break; } if (!valid) throw \"request supports no\nsuch callback \'\" + cbName + \"\'\"; // send callback invocation postMessage({ id:\nid, callback: cbName, params: v}); }, error: function(error, message) {\ncompleted = true; // verify in table if (!inTbl[id]) throw \"error called for\nnonexistent message: \" + id; // remove transaction from table delete inTbl[id];\n// send error postMessage({ id: id, error: error, message: message }); },\ncomplete: function(v) { completed = true; // verify in table if (!inTbl[id])\nthrow \"complete called for nonexistent message: \" + id; // remove transaction\nfrom table delete inTbl[id]; // send complete postMessage({ id: id, result: v\n}); }, delayReturn: function(delay) { if (typeof delay === \'boolean\') {\nshouldDelayReturn = (delay === true); } return shouldDelayReturn; }, completed:\nfunction() { return completed; } }; }; var setTransactionTimeout = function\n(transId, timeout, method) { return window.setTimeout(function() { if (outTbl\n[transId]) { // XXX: what if client code raises an exception here? var msg =\n\"timeout (\" + timeout + \"ms) exceeded on method \'\" + method + \"\'\"; (1,outTbl\n[transId].error)(\"timeout_error\", msg); delete outTbl[transId]; delete\ns_transIds[transId]; } }, timeout); }; var onMessage = function(origin, method,\nm) { // if an observer was specified at allocation time, invoke it if (typeof\ncfg.gotMessageObserver === \'function\') { // pass observer a clone of the object\nso that our // manipulations are not visible (i.e. method unscoping). // This\nis not particularly efficient, but then we expect // that message observers are\nprimarily for debugging anyway. try { cfg.gotMessageObserver(origin, m); }\ncatch (e) { debug(\"gotMessageObserver() raised an exception: \" + e.toString());\n} } // now, what type of message is this? if (m.id && method) { // a request!\ndo we have a registered handler for this request? if (regTbl[method]) { var\ntrans = createTransaction(m.id, origin, m.callbacks ? m.callbacks : [ ]); inTbl\n[m.id] = { }; try { // callback handling. we\'ll magically create functions\ninside the parameter list for each // callback if (m.callbacks && s_isArray\n(m.callbacks) && m.callbacks.length > 0) { for (var i = 0; i <\nm.callbacks.length; i++) { var path = m.callbacks[i]; var obj = m.params; var\npathItems = path.split(\'/\'); for (var j = 0; j < pathItems.length - 1; j++) {\nvar cp = pathItems[j]; if (typeof obj[cp] !== \'object\') obj[cp] = { }; obj =\nobj[cp]; } obj[pathItems[pathItems.length - 1]] = (function() { var cbName =\npath; return function(params) { return trans.invoke(cbName, params); }; })(); }\n} var resp = regTbl[method](trans, m.params); if (!trans.delayReturn() && !\ntrans.completed()) trans.complete(resp); } catch(e) { // automagic handling of\nexceptions: var error = \"runtime_error\"; var message = null; // * if it\'s a\nstring then it gets an error code of \'runtime_error\' and string is the message\nif (typeof e === \'string\') { message = e; } else if (typeof e === \'object\') { /\n/ either an array or an object // * if it\'s an array of length two, then array\n[0] is the code, array[1] is the error message if (e && s_isArray(e) &&\ne.length == 2) { error = e[0]; message = e[1]; } // * if it\'s an object then\nwe\'ll look form error and message parameters else if (typeof e.error ===\n\'string\') { error = e.error; if (!e.message) message = \"\"; else if (typeof\ne.message === \'string\') message = e.message; else e = e.message; // let the\nstringify/toString message give us a reasonable verbose error string } } //\nmessage is *still* null, let\'s try harder if (message === null) { try { message\n= JSON.stringify(e); /* On MSIE8, this can result in \'out of memory\', which *\nleaves message undefined. */ if (typeof(message) == \'undefined\') message =\ne.toString(); } catch (e2) { message = e.toString(); } } trans.error\n(error,message); } } } else if (m.id && m.callback) { if (!outTbl[m.id] ||!\noutTbl[m.id].callbacks || !outTbl[m.id].callbacks[m.callback]) { debug\n(\"ignoring invalid callback, id:\"+m.id+ \" (\" + m.callback +\")\"); } else { //\nXXX: what if client code raises an exception here? outTbl[m.id].callbacks\n[m.callback](m.params); } } else if (m.id) { if (!outTbl[m.id]) { debug\n(\"ignoring invalid response: \" + m.id); } else { // XXX: what if client code\nraises an exception here? if (m.error) { (1,outTbl[m.id].error)(m.error,\nm.message); } else { if (m.result !== undefined) (1,outTbl[m.id].success)\n(m.result); else (1,outTbl[m.id].success)(); } delete outTbl[m.id]; delete\ns_transIds[m.id]; } } else if (method) { // tis a notification. if (regTbl\n[method]) { // yep, there\'s a handler for that. // transaction has only origin\nfor notifications. regTbl[method]({ origin: origin }, m.params); // if the\nclient throws, we\'ll just let it bubble out // what can we do? Also, here we\'ll\nignore return values } } }; // now register our bound channel for msg routing\ns_addBoundChan(cfg.window, cfg.origin, ((typeof cfg.scope === \'string\') ?\ncfg.scope : \'\'), onMessage); // scope method names based on cfg.scope specified\nwhen the Channel was instantiated var scopeMethod = function(m) { if (typeof\ncfg.scope === \'string\' && cfg.scope.length) m = [cfg.scope, m].join(\"::\");\nreturn m; }; // a small wrapper around postmessage whose primary function is to\nhandle the // case that clients start sending messages before the other end is\n\"ready\" var postMessage = function(msg, force) { if (!msg) throw \"postMessage\ncalled with null message\"; // delay posting if we\'re not ready yet. var verb =\n(ready ? \"post \" : \"queue \"); debug(verb + \" message: \" + JSON.stringify(msg));\nif (!force && !ready) { pendingQueue.push(msg); } else { if (typeof\ncfg.postMessageObserver === \'function\') { try { cfg.postMessageObserver\n(cfg.origin, msg); } catch (e) { debug(\"postMessageObserver() raised an\nexception: \" + e.toString()); } } cfg.window.postMessage(JSON.stringify(msg),\ncfg.origin); } }; var onReady = function(trans, type) { debug(\'ready msg\nreceived\'); if (ready) throw \"received ready message while in ready state.\nhelp!\"; if (type === \'ping\') { chanId += \'-R\'; } else { chanId += \'-L\'; }\nobj.unbind(\'__ready\'); // now this handler isn\'t needed any more. ready = true;\ndebug(\'ready msg accepted.\'); if (type === \'ping\') { obj.notify({ method:\n\'__ready\', params: \'pong\' }); } // flush queue while (pendingQueue.length) {\npostMessage(pendingQueue.pop()); } // invoke onReady observer if provided if\n(typeof cfg.onReady === \'function\') cfg.onReady(obj); }; var obj = { // tries\nto unbind a bound message handler. returns false if not possible unbind:\nfunction (method) { if (regTbl[method]) { if (!(delete regTbl[method])) throw\n(\"can\'t delete method: \" + method); return true; } return false; }, bind:\nfunction (method, cb) { if (!method || typeof method !== \'string\') throw\n\"\'method\' argument to bind must be string\"; if (!cb || typeof cb !==\n\'function\') throw \"callback missing from bind params\"; if (regTbl[method])\nthrow \"method \'\"+method+\"\' is already bound!\"; regTbl[method] = cb; return\nthis; }, call: function(m) { if (!m) throw \'missing arguments to call\nfunction\'; if (!m.method || typeof m.method !== \'string\') throw \"\'method\'\nargument to call 