n.w;\\n\\n // how much features are squished\nin the y direction by the tilt\\n float squish_scale = length(a_extrude) /\nlength(u_antialiasingmatrix * a_extrude);\\n\\n // how much features are squished\nin all directions by the perspectiveness\\n float perspective_scale = 1.0 / (1.0\n- min(y * u_extra, 0.9));\\n\\n v_linewidth = vec2(outset, inset);\\n\nv_gamma_scale = perspective_scale * squish_scale;\\n}\\n\"},linesdfpattern:\n{fragmentSource:\"#ifdef GL_ES\\nprecision mediump float;\\n#else\\n#define lowp\\n#\ndefine mediump\\n#define highp\\n#endif\\n\\nuniform lowp vec4 u_color;\\nuniform\nlowp float u_opacity;\\n\\nuniform float u_blur;\\nuniform sampler2D u_image;\\\nnuniform float u_sdfgamma;\\nuniform float u_mix;\\n\\nvarying vec2 v_normal;\\\nnvarying vec2 v_linewidth;\\nvarying vec2 v_tex_a;\\nvarying vec2 v_tex_b;\\\nnvarying float v_gamma_scale;\\n\\nvoid main() {\\n // Calculate the distance of\nthe pixel from the line in pixels.\\n float dist = length(v_normal) *\nv_linewidth.s;\\n\\n // Calculate the antialiasing fade factor. This is either\nwhen fading in\\n // the line in case of an offset line (v_linewidth.t) or when\nfading out\\n // (v_linewidth.s)\\n float blur = u_blur * v_gamma_scale;\\n float\nalpha = clamp(min(dist - (v_linewidth.t - blur), v_linewidth.s - dist) / blur,\n0.0, 1.0);\\n\\n float sdfdist_a = texture2D(u_image, v_tex_a).a;\\n float\nsdfdist_b = texture2D(u_image, v_tex_b).a;\\n float sdfdist = mix(sdfdist_a,\nsdfdist_b, u_mix);\\n alpha *= smoothstep(0.5 - u_sdfgamma, 0.5 + u_sdfgamma,\nsdfdist);\\n\\n gl_FragColor = u_color * (alpha * u_opacity);\\n\\n#ifdef\nOVERDRAW_INSPECTOR\\n gl_FragColor = vec4(1.0);\\n#endif\\n}\\n\",vertexSource:\"#\nifdef GL_ES\\nprecision highp float;\\n#else\\n#define lowp\\n#define mediump\\n#\ndefine highp\\n#endif\\n\\n// floor(127 / 2) == 63.0\\n// the maximum allowed miter\nlimit is 2.0 at the moment. the extrude normal is\\n// stored in a byte\n(-128..127). we scale regular normals up to length 63, but\\n// there are also \\\n\"special\\\" normals that have a bigger length (of up to 126 in\\n// this case).\\n\n// #define scale 63.0\\n#define scale 0.015873016\\n\\n// We scale the distance\nbefore adding it to the buffers so that we can store\\n// long distances for\nlong segments. Use this value to unscale the distance.\\n#define\nLINE_DISTANCE_SCALE 2.0\\n\\nattribute vec2 a_pos;\\nattribute vec4 a_data;\\n\\\nnuniform mat4 u_matrix;\\nuniform mediump float u_ratio;\\nuniform mediump float\nu_linewidth;\\nuniform mediump float u_gapwidth;\\nuniform mediump float\nu_antialiasing;\\nuniform vec2 u_patternscale_a;\\nuniform float u_tex_y_a;\\\nnuniform vec2 u_patternscale_b;\\nuniform float u_tex_y_b;\\nuniform float\nu_extra;\\nuniform mat2 u_antialiasingmatrix;\\nuniform mediump float u_offset;\\n\n\\nvarying vec2 v_normal;\\nvarying vec2 v_linewidth;\\nvarying vec2 v_tex_a;\\\nnvarying vec2 v_tex_b;\\nvarying float v_gamma_scale;\\n\\nvoid main() {\\n vec2\na_extrude = a_data.xy - 128.0;\\n float a_direction = mod(a_data.z, 4.0) - 1.0;\\\nn float a_linesofar = (floor(a_data.z / 4.0) + a_data.w * 64.0) *\nLINE_DISTANCE_SCALE;\\n\\n // We store the texture normals in the most\ninsignificant bit\\n // transform y so that 0 => -1 and 1 => 1\\n // In the\ntexture normal, x is 0 if the normal points straight up/down and 1 if it\'s a\nround cap\\n // y is 1 if the normal points up, and -1 if it points down\\n\nmediump vec2 normal = mod(a_pos, 2.0);\\n normal.y = sign(normal.y - 0.5);\\n\nv_normal = normal;\\n\\n float inset = u_gapwidth + (u_gapwidth > 0.0 ?\nu_antialiasing : 0.0);\\n float outset = u_gapwidth + u_linewidth * (u_gapwidth\n> 0.0 ? 2.0 : 1.0) + u_antialiasing;\\n\\n // Scale the extrusion vector down to\na normal and then up by the line width\\n // of this vertex.\\n mediump vec2 dist\n= outset * a_extrude * scale;\\n\\n // Calculate the offset when drawing a line\nthat is to the side of the actual line.\\n // We do this by creating a vector\nthat points towards the extrude, but rotate\\n // it when we\'re drawing round\nend points (a_direction = -1 or 1) since their\\n // extrude vector points in\nanother direction.\\n mediump float u = 0.5 * a_direction;\\n mediump float t =\n1.0 - abs(u);\\n mediump vec2 offset = u_offset * a_extrude * scale * normal.y *\nmat2(t, -u, u, t);\\n\\n // Remove the texture normal bit of the position before\nscaling it with the\\n // model/view matrix.\\n gl_Position = u_matrix * vec4\n(floor(a_pos * 0.5) + (offset + dist) / u_ratio, 0.0, 1.0);\\n\\n v_tex_a = vec2\n(a_linesofar * u_patternscale_a.x, normal.y * u_patternscale_a.y + u_tex_y_a);\\\nn v_tex_b = vec2(a_linesofar * u_patternscale_b.x, normal.y *\nu_patternscale_b.y + u_tex_y_b);\\n\\n // position of y on the screen\\n float y =\ngl_Position.y / gl_Position.w;\\n\\n // how much features are squished in the y\ndirection by the tilt\\n float squish_scale = length(a_extrude) / length\n(u_antialiasingmatrix * a_extrude);\\n\\n // how much features are squished in\nall directions by the perspectiveness\\n float perspective_scale = 1.0 / (1.0 -\nmin(y * u_extra, 0.9));\\n\\n v_linewidth = vec2(outset, inset);\\n v_gamma_scale\n= perspective_scale * squish_scale;\\n}\\n\"},outline:{fragmentSource:\"#ifdef\nGL_ES\\nprecision mediump float;\\n#else\\n#define lowp\\n#define mediump\\n#define\nhighp\\n#endif\\n\\n#pragma mapbox: define lowp vec4 outline_color\\n#pragma\nmapbox: define lowp float opacity\\n\\nvarying vec2 v_pos;\\n\\nvoid main() {\\n #\npragma mapbox: initialize lowp vec4 outline_color\\n #pragma mapbox: initialize\nlowp float opacity\\n\\n float dist = length(v_pos - gl_FragCoord.xy);\\n float\nalpha = smoothstep(1.0, 0.0, dist);\\n gl_FragColor = outline_color * (alpha *\nopacity);\\n\\n#ifdef OVERDRAW_INSPECTOR\\n gl_FragColor = vec4(1.0);\\n#endif\\n}\\\nn\",vertexSource:\"#ifdef GL_ES\\nprecision highp float;\\n#else\\n#define lowp\\n#\ndefine mediump\\n#define highp\\n#endif\\n\\nattribute vec2 a_pos;\\n\\nuniform mat4\nu_matrix;\\nuniform vec2 u_world;\\n\\nvarying vec2 v_pos;\\n\\n#pragma mapbox:\ndefine lowp vec4 outline_color\\n#pragma mapbox: define lowp float opacity\\n\\\nnvoid main() {\\n #pragma mapbox: initialize lowp vec4 outline_color\\n #pragma\nmapbox: initialize lowp float opacity\\n\\n gl_Position = u_matrix * vec4(a_pos,\n0, 1);\\n v_pos = (gl_Position.xy / gl_Position.w + 1.0) / 2.0 * u_world;\\n}\\\nn\"},outlinepattern:{fragmentSource:\"#ifdef GL_ES\\nprecision mediump float;\\n#\nelse\\n#define lowp\\n#define mediump\\n#define highp\\n#endif\\n\\nuniform float\nu_opacity;\\nuniform vec2 u_pattern_tl_a;\\nuniform vec2 u_pattern_br_a;\\nuniform\nvec2 u_pattern_tl_b;\\nuniform vec2 u_pattern_br_b;\\nuniform float u_mix;\\n\\\nnuniform sampler2D u_image;\\n\\nvarying vec2 v_pos_a;\\nvarying vec2 v_pos_b;\\\nnvarying vec2 v_pos;\\n\\nvoid main() {\\n vec2 imagecoord = mod(v_pos_a, 1.0);\\n\nvec2 pos = mix(u_pattern_tl_a, u_pattern_br_a, imagecoord);\\n vec4 color1 =\ntexture2D(u_image, pos);\\n\\n vec2 imagecoord_b = mod(v_pos_b, 1.0);\\n vec2 pos2\n= mix(u_pattern_tl_b, u_pattern_br_b, imagecoord_b);\\n vec4 color2 = texture2D\n(u_image, pos2);\\n\\n // find distance to outline for alpha interpolation\\n\\n\nfloat dist = length(v_pos - gl_FragCoord.xy);\\n float alpha = smoothstep(1.0,\n0.0, dist);\\n \\n\\n gl_FragColor = mix(color1, color2, u_mix) * alpha *\nu_opacity;\\n\\n#ifdef OVERDRAW_INSPECTOR\\n gl_FragColor = vec4(1.0);\\n#endif\\n}\\\nn\",vertexSource:\"#ifdef GL_ES\\nprecision highp float;\\n#else\\n#define lowp\\n#\ndefine mediump\\n#define highp\\n#endif\\n\\nuniform vec2 u_pattern_size_a;\\\nnuniform vec2 u_pattern_size_b;\\nuniform vec2 u_pixel_coord_upper;\\nuniform\nvec2 u_pixel_coord_lower;\\nuniform float u_scale_a;\\nuniform float u_scale_b;\\\nnuniform float u_tile_units_to_pixels;\\n\\nattribute vec2 a_pos;\\n\\nuniform mat4\nu_matrix;\\nuniform vec2 u_world;\\n\\nvarying vec2 v_pos_a;\\nvarying vec2\nv_pos_b;\\nvarying vec2 v_pos;\\n\\nvoid main() {\\n gl_Position = u_matrix * vec4\n(a_pos, 0, 1);\\n vec2 scaled_size_a = u_scale_a * u_pattern_size_a;\\n vec2\nscaled_size_b = u_scale_b * u_pattern_size_b;\\n\\n // the correct offset needs\nto be calculated.\\n //\\n // The offset depends on how many pixels are between\nthe world origin and\\n // the edge of the tile:\\n // vec2 offset = mod\n(pixel_coord, size)\\n //\\n // At high zoom levels there are a ton of pixels\nbetween the world origin\\n // and the edge of the tile. The glsl spec only\nguarantees 16 bits of\\n // precision for highp floats. We need more than that.\\\nn //\\n // The pixel_coord is passed in as two 16 bit values:\\n //\npixel_coord_upper = floor(pixel_coord / 2^16)\\n // pixel_coord_lower = mod\n(pixel_coord, 2^16)\\n //\\n // The offset is calculated in a series of steps\nthat should preserve this precision:\\n vec2 offset_a = mod(mod(mod\n(u_pixel_coord_upper, scaled_size_a) * 256.0, scaled_size_a) * 256.0 +\nu_pixel_coord_lower, scaled_size_a);\\n vec2 offset_b = mod(mod(mod\n(u_pixel_coord_upper, scaled_size_b) * 256.0, scaled_size_b) * 256.0 +\nu_pixel_coord_lower, scaled_size_b);\\n\\n v_pos_a = (u_tile_units_to_pixels *\na_pos + offset_a) / scaled_size_a;\\n v_pos_b = (u_tile_units_to_pixels * a_pos\n+ offset_b) / scaled_size_b;\\n\\n v_pos = (gl_Position.xy / gl_Position.w + 1.0)\n/ 2.0 * u_world;\\n}\\n\"},pattern:{fragmentSource:\"#ifdef GL_ES\\nprecision\nmediump float;\\n#else\\n#define lowp\\n#define mediump\\n#define highp\\n#endif\\n\\\nnuniform float u_opacity;\\nuniform vec2 u_pattern_tl_a;\\nuniform vec2\nu_pattern_br_a;\\nuniform vec2 u_pattern_tl_b;\\nuniform vec2 u_pattern_br_b;\\\nnuniform float u_mix;\\n\\nuniform sampler2D u_image;\\n\\nvarying vec2 v_pos_a;\\\nnvarying vec2 v_pos_b;\\n\\nvoid main() {\\n\\n vec2 imagecoord = mod(v_pos_a,\n1.0);\\n vec2 pos = mix(u_pattern_tl_a, u_pattern_br_a, imagecoord);\\n vec4\ncolor1 = texture2D(u_image, pos);\\n\\n vec2 imagecoord_b = mod(v_pos_b, 1.0);\\n\nvec2 pos2 = mix(u_pattern_tl_b, u_pattern_br_b, imagecoord_b);\\n vec4 color2 =\ntexture2D(u_image, pos2);\\n\\n gl_FragColor = mix(color1, color2, u_mix) *\nu_opacity;\\n\\n#ifdef OVERDRAW_INSPECTOR\\n gl_FragColor = vec4(1.0);\\n#endif\\n}\\\nn\",vertexSource:\"#ifdef GL_ES\\nprecision highp float;\\n#else\\n#define lowp\\n#\ndefine mediump\\n#define highp\\n#endif\\n\\nuniform mat4 u_matrix;\\nuniform vec2\nu_pattern_size_a;\\nuniform vec2 u_pattern_size_b;\\nuniform vec2\nu_pixel_coord_upper;\\nuniform vec2 u_pixel_coord_lower;\\nuniform float\nu_scale_a;\\nuniform float u_scale_b;\\nuniform float u_tile_units_to_pixels;\\n\\\nnattribute vec2 a_pos;\\n\\nvarying vec2 v_pos_a;\\nvarying vec2 v_pos_b;\\n\\nvoid\nmain() {\\n gl_Position = u_matrix * vec4(a_pos, 0, 1);\\n vec2 scaled_size_a =\nu_scale_a * u_pattern_size_a;\\n vec2 scaled_size_b = u_scale_b *\nu_pattern_size_b;\\n\\n // the correct offset needs to be calculated.\\n //\\n //\nThe offset depends on how many pixels are between the world origin and\\n // the\nedge of the tile:\\n // vec2 offset = mod(pixel_coord, size)\\n //\\n // At high\nzoom levels there are a ton of pixels between the world origin\\n // and the\nedge of the tile. The glsl spec only guarantees 16 bits of\\n // precision for\nhighp floats. We need more than that.\\n //\\n // The pixel_coord is passed in as\ntwo 16 bit values:\\n // pixel_coord_upper = floor(pixel_coord / 2^16)\\n //\npixel_coord_lower = mod(pixel_coord, 2^16)\\n //\\n // The offset is calculated\nin a series of steps that should preserve this precision:\\n vec2 offset_a = mod\n(mod(mod(u_pixel_coord_upper, scaled_size_a) * 256.0, scaled_size_a) * 256.0 +\nu_pixel_coord_lower, scaled_size_a);\\n vec2 offset_b = mod(mod(mod\n(u_pixel_coord_upper, scaled_size_b) * 256.0, scaled_size_b) * 256.0 +\nu_pixel_coord_lower, scaled_size_b);\\n\\n v_pos_a = (u_tile_units_to_pixels *\na_pos + offset_a) / scaled_size_a;\\n v_pos_b = (u_tile_units_to_pixels * a_pos\n+ offs