t: 0;\n}\n.ui-header .ui-last-wrap {\n  right: 0;\n}\n/* double borders */\nhtml .ui-header .ui-first-wrap .ui-controlgroup-controls .ui-btn {\n  border-right: 1px solid rgb(232, 232, 232);\n  border-right: 1px solid rgba(232, 232, 232, 0.5);\n}\nhtml .ui-header .ui-last-wrap .ui-controlgroup-controls .ui-btn {\n  border-left: 1px solid rgb(47, 79, 79);\n  border-left: 1px solid rgba(0, 0, 0, 0.25);\n}\n.ui-header .ui-first-wrap .ui-btn:before,\n.ui-header .ui-last-wrap .ui-btn:before {\n  content: \"\";\n  height: 100%;\n  position: absolute;\n  width: 0;\n  bottom: 0;\n  top: 0;\n}\n.ui-header .ui-first-wrap .ui-btn:before {\n  right: 0px;\n  border-right: 1px solid rgb(47, 79, 79);\n  border-right: 1px solid rgba(0, 0, 0, 0.25);\n}\n.ui-header .ui-last-wrap .ui-btn:before {\n  left: 0px;\n  border-left: 1px solid rgb(232, 232, 232);\n  border-left: 1px solid rgba(232, 232, 232, 0.5);\n}\n/* form & fieldcontain */\n/* set label/input width on large screens */\n/* TODO: form fields should auto-expand to full width */\n@media (min-width: 40em) {\n  .ui-fieldcontain label:not(.ui-btn),\n  .ui-fieldcontain div.ui-input-text,\n  .ui-fieldcontain div.ui-input-search,\n  .ui-fieldcontain div.ui-select {\n    display: inline-block;\n    vertical-align: middle;\n  }\n  .ui-fieldcontain label:not(.ui-btn) {\n    width: 46% /*40%*/;\n  }\n  .ui-fieldcontain div.ui-input-text,\n  .ui-fieldcontain div.ui-input-search {\n    width: 50%;\n  }\n  .ui-fieldcontain div.ui-select {\n    width: 56%;\n  }\n  .ui-fieldcontain div.ui-select .ui-btn {\n    -webkit-box-shadow: none;\n    -moz-box-shadow: none;\n    box-shadow: none;\n    min-height: 19px;\n    padding-top: 5px;\n    padding-bottom: 5px;\n  }\n  .ui-fieldcontain div.ui-select .ui-btn.ui-btn-icon-right:after {\n    right: 0.25em;\n  }\n}\n\n/* ============================= forms ============================= */\n/*\nform {\n  font-size: .85em;\n}\nform p {\n  font-size: 1em;\n}\n@media (max-width: 40em) {\n  form {\n    font-size: 1em;\n  }\n}\n*/\n/* ============================= content grid ============================= */\n.span_1, .span_2 {\n  display: inline-block;\n  vertical-align: middle;\n  width: 45%;\n  padding-left: 2%;\n  padding-right: 2%;\n  /* ~ 98% for 2 col layout */\n  padding-top: 2%;\n}\n.span_1 textarea {\n  width: 56%;\n  display: inline-block;\n  vertical-align: middle;\n}\n.span_2 {\n  width: 96% /* 2% padding-left/right */\n}\n/* is this padding really necessary? */\n.span_1 .ui-controlgroup-vertical,\n.span_2 .ui-controlgroup-vertical,\n.span_1 .ui-controlgroup-horizontal,\n.span_2 .ui-controlgroup-horizontal,\n.span_1 form,\n.span_2 form {\n  margin-top: 1em;\n  margin-bottom: 1em;\n  vertical-align: middle;\n}\n@media (max-width: 40em) {\n  .span_1, .span_2 {\n    width: 100%;\n    padding: 0;\n  }\n  .span_1 textarea {\n    width: 100%;\n  }\n}\n.span_1 .ui-input-search,\n.span_2 .ui-input-search {\n  width: 50%;\n}\n.span_1 .ui-table-wrapper .ui-input-search,\n.span_2 .ui-table-wrapper .ui-input-search{\n  width: auto;\n  margin: 0;\n  box-shadow: none;\n  -webkit-box-shadow: none;\n  border-width: 0;\n  border-bottom-width: 1px;\n}\n@media (max-width: 45em) {\n  .span_1 .ui-input-search,\n  .span_2 .ui-input-search {\n    width: 100%;\n  }\n}\n@media (min-width: 45em) {\n  .span_1 .ui-input-search,\n  .span_2 .ui-input-search {\n    width: 60%;\n  }\n}\n/* ============================= content elements ============================= */\n/* TODO: merge with span_1 span_2... */\nhtml div.ui-page div.ui-content .ui-content-element {\n  /* TODO: should have corners and shadow - but not like this!*/\n  /*\n  -webkit-box-shadow: 0 1px 3px rgba(0,0,0,.15);\n  -moz-box-shadow: 0 1px 3px rgba(0,0,0,.15);\n  box-shadow: 0 1px 3px rgba(0,0,0,.15);\n  */\n  -webkit-border-radius:  .3125em;\n  border-radius: .3125em;\n  border: 1px solid #aaa;\n  padding: 1em;\n  margin: 1em auto;\n  text-align: center;\n}\nhtml div.ui-page div.ui-content .ui-content-element > .ui-btn {\n  max-width: 10%;\n  margin: 1em auto 0;\n  display: block;\n}\n\n\n.panel .ui-panel-inner .panel_element {\n  margin-left: -1em;\n  margin-right: -1em;\n}\n.panel .ui-panel-inner .panel_element.panel_element_first {\n  margin-top: -1em;\n}\n.panel .ui-panel-inner .panel_element.panel_element_last {\n  margin-bottom: -1em;\n}\n.panel .panel_element.panel_header {\n  border-width: 0;\n  padding-top: 1px;\n  top: -1px;\n}\n\n/* navbar */\n.navbar ul li a.ui-btn-active.clone_item span.navbar_clone {\n  font-weight: bold;\n}\n/* controlgroup */\n.ui-header .ui-controlgroup,\n.ui-header .ui-controlgroup fieldset.ui-controlgroup,\n/* controlgroup header outside of page */\n.ui-controlgroup,\n.ui-controlgroup fieldset.ui-controlgroup{\n  padding: 0;\n  margin: 0;\n  height: 100%;\n}\n.ui-header .ui-controlgroup-controls {\n  height: 100%;\n}\n/* single button controlgroup */\n.ui-controlgroup.ui-corner-all .ui-controlgroup-controls .ui-btn.ui-first-child.ui-last-child {\n  border-radius: inherit;\n}\n/* button  */\n.ui-header a.ui-btn ,\nhtml .ui-header a.ui-btn ,\nhtml body .ui-header a.ui-btn,\nhtml body .ui-header .ui-controlgroup .ui-controlgroup-controls div.ui-select .ui-btn{\n  height: 100%;\n  margin: 0;\n  position: relative; /* otherwise multiple buttons break */\n  padding-top: 0;\n  padding-bottom: 0;\n  border-radius: 0;\n  -webkit-border-radius: 0;\n}\nhtml .ui-btn, label.ui-btn {\n  font-weight: normal;\n}\n\n/* no bold buttons */\nhtml .ui-btn, label.ui-btn {\n  font-weight: normal;\n}\n/* fix svg icon positioning */\n.ui-btn-icon-notext:after,\n.ui-btn-icon-left:after,\n.ui-btn-icon-right:after,\n.ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after {\n  margin-top: -15px;\n}\n/* reset fix */\n.ui-nosvg .ui-btn-icon-notext:after,\n.ui-nosvg .ui-btn-icon-left:after,\n.ui-nosvg .ui-btn-icon-right:after,\n.ui-nosvg .ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after,\n.ui-input-clear.ui-btn-icon-notext:after {\n  margin-top: -11px;\n}\n/* fix text-indent when trying to use custom icons on iconpos-notext buttons */\n.ui-btn-icon-notext {\n  text-indent: -9999px;\n}\n.ui-btn-icon-notext:after {\n  text-indent: 0px;\n}\n/* fix font-size on notext buttons, so icons don\'t zoom, JQMs-px font-size */\n.ui-header .ui-btn-icon-notext,\n.ui-footer .ui-btn-icon-notext {\n  font-size: 12.5px;\n}\n\n/* popup */\n.ui-popup {\n  max-width: 20em; /* so... all popups should get this??? */\n  /* width: 25%; does not work, because max-width will still be screen-padding */\n  min-width: 20em;\n  margin: 0 auto;\n}\n.ui-popup.ui-popup-wide {\n  max-width: 40em;\n  min-width: 40em;\n}\n@media (max-width: 40em) {\n  .ui-popup, html .ui-popup.ui-popup-wide {\n    min-width: 0;\n    margin: 0;\n    width: auto;\n  }\n}\n.ui-popup fieldset {\n  display: block; /* fix offset caused when using display: table-column */\n}\n\n/* all of this should go into a single wrapper/toolbar widget */\n.ui-popup.ui-popup-wide form.draggable div.ui-grid-row {\n  cursor: move;\n}\n.ui-popup.ui-popup-wide form div.ui-grid-row {\n  padding-top: .25em;\n  border-bottom: 1px solid rgba(0, 0, 0, .1);\n}\n.ui-popup.ui-popup-wide form .ui-grid-title {\n  max-width: 25%;\n}\n.ui-popup.ui-popup-wide form .ui-grid-search {\n  min-width: 35%;\n  width: auto;\n}\n@media (max-width: 40em) {\n.ui-popup.ui-popup-wide form .ui-grid-search {\n  max-width: 35%;\n}\n}\n.ui-popup.ui-popup-wide form .ui-grid-action {\n  max-width: 5%;\n}\n.ui-popup.ui-popup-wide form .ui-block-a,\n.ui-popup.ui-popup-wide form .ui-block-b,\n.ui-popup.ui-popup-wide form .ui-block-c,\n.ui-popup.ui-popup-wide form .ui-block-d {\n  height: 2.5em;\n  line-height: 2.5em;\n  vertical-align: middle;\n}\n.ui-popup.ui-popup-wide div > p {\n  padding: 0 15px;\n  text-align: center;\n}\n.ui-popup.ui-popup-wide .ui-slider.ui-mini {\n  margin-top: 0;\n  margin-bottom: 0;\n}\n.ui-popup.ui-popup-wide form .ui-grid-title span {\n  display: table-cell;\n  padding: 0.25em 0 0.25em 0.5em;\n  font-size: .9em;\n}\n.ui-popup.ui-popup-wide form .ui-input-text {\n  margin: 0 0.5em;\n}\n.ui-popup.ui-popup-wide .ui-grid-3,\n.ui-popup.ui-popup-narrow .ui-grid-3,\n.ui-popup.ui-popup-wide .ui-grid-2,\n.ui-popup.ui-popup-narrow .ui-grid-2 {\n  margin: 0;\n}\n.ui-popup.ui-popup-wide .ui-popup-menu,\n.ui-popup.ui-popup-narrow .ui-popup-menu {\n  text-align: center;\n  margin-bottom: .5em;\n}\n.ui-popup.ui-popup-wide .ui-popup-menu .ui-controlgroup-controls .ui-btn,\n.ui-popup.ui-popup-wide .ui-grid-row .ui-select .ui-btn,\n.ui-popup.ui-popup-narrow .ui-popup-menu .ui-controlgroup-controls .ui-btn {\n  font-size: 85%;\n}\n.ui-popup.ui-popup-wide .ui-grid-row .ui-select,\n.ui-popup.ui-popup-wide .ui-grid-row .ui-checkbox {\n  margin-top: 0;\n  margin-bottom: 0;\n}\n.ui-popup.ui-popup-wide .ui-popup-menu .ui-controlgroup-controls .ui-btn:after,\n.ui-popup.ui-popup-narrow .ui-popup-menu .ui-controlgroup-controls .ui-btn:after{\n  margin-top: -12px;\n}\n.ui-popup.ui-popup-wide .ui-grid-3.ui-controlgroup-controls,\n.ui-popup.ui-popup-wide .ui-grid-2.ui-controlgroup-controls,\n.ui-popup.ui-popup-narrow .ui-grid-3.ui-controlgroup-controls,\n.ui-popup.ui-popup-narrow .ui-grid-2.ui-controlgroup-controls {\n  width: 100%;\n}\n.ui-popup.ui-popup-wide .ui-grid-3 a.ui-btn,\n.ui-popup.ui-popup-narrow .ui-grid-3 a.ui-btn{\n  width: 33.33%;\n  box-sizing: padding-box;\n  -moz-box-sizing: padding-box;\n  -webkit-box-sizing: padding-box;\n  border-width: 0px;\n}\n.ui-popup.ui-popup-wide .ui-grid-2 a.ui-btn,\n.ui-popup.ui-popup-narrow .ui-grid-2 a.ui-btn{\n  width: 50%;\n  box-sizing: padding-box;\n  -moz-box-sizing: padding-box;\n  -webkit-box-sizing: padding-box;\n  border-width: 0px;\n}\n\n\n/* panel */\n.ui-panel {\n  border-width: 0px; /* overwrite border-width reset by panel-swatch ui-overlay... */\n}\n/* panel closer */\nhtml .ui-panel-inner .ui-btn.panel-close {\n  background-color: transparent;\n  background-image: none;\n  margin: 12px 0.3125em 0; /* no friend ... */\n}\nhtml .ui-panel-inner .ui-btn.panel-close:hover {\n  border-color: transparent;\n}\nhtml .ui-panel-inner .ui-btn.panel-close:after {\n  font-size: 1.25em;\n  margin-top: -12px; /* no friend ... */\n}\nhtml .ui-btn.panel-close {\n  position: absolute !important;\n  top: -9999px;\n  left: -9999px;\n  clip: rect(1px 1px 1px 1px);\n  display: none;\n}\n@media (max-width: 30em) {\n  html .ui-btn.panel-close {\n    right: 0;\n    top: 0;\n    left: auto;\n    clip: auto;\n    display: block;\n  }\n}\n/* panel search input overriding width */\nhtml .ui-panel-inner .ui-input-search {\n  margin: 2% 1%;\n}\n@media (max-width: 30em) {\n  html .ui-panel-inner .ui-input-search {\n    width: 77%;\n  }\n}\n\n@media (max-width: 25em) {\n  html .ui-panel-inner .ui-input-search {\n    width: 77%;\n  }\n}\n@media (max-width: 20em) {\n  html .ui-panel-inner .ui-input-search {\n    width: 77%;\n  }\n}\n/* filterable */\nhtml .ui-filterable {\n  width: 75%;\n  margin: 0 auto;\n}\n@media (max-width: 40em) {\n  html .ui-filterable  {\n    width: 100%;\n    margin: 0.5em 0;\n  }\n}\n\n/* extend panel to fullwidth on small screens */\n@media (max-width: 30em) {\n  /* override JQM 17em */\n  .ui-panel {\n    width: 100%;\n  }\n  /* positioning: panel */\n  /* panel left  */\n  .ui-panel-position-left {\n    left: -100%;\n  }\n  /* animated: panel left (for overlay and push) */\n  .ui-panel-animate.ui-panel-position-left.ui-panel-display-overlay,\n  .ui-panel-animate.ui-panel-position-left.ui-panel-display-push {\n    left: 0;\n    -webkit-transform: translate3d(-100%,0,0);\n    -moz-transform: translate3d(-100%,0,0);\n    transform: translate3d(-100%,0,0);\n  }\n  /* panel left open */\n  .ui-panel-position-left.ui-panel-display-reveal, /* negate \"panel left\" for reveal */\n  .ui-panel-position-left.ui-panel-open {\n    left: 0;\n  }\n  /* animated: panel left open (for overlay and push) */\n  .ui-panel-animate.ui-panel-position-left.ui-panel-open.ui-panel-display-overlay,\n  .ui-panel-animate.ui-panel-position-l