tle for my global graph\"} } }'),(13863,'Field Graph With Echarts gadget_field_graph_echarts.js /*global window, rJS, RSVP, echarts, loopEventListener */ /*jslint nomen: true,\nindent: 2 */ (function (window, rJS, RSVP, echarts, loopEventListener) { \"use\nstrict\"; ///////////////////////////////////////////////////////////////// //\ntemplates ///////////////////////////////////////////////////////////////// var\ngadget_klass = rJS(window), getGraphDataAndParameterFromConfiguration =\nfunction (configuration_dict) { var graph_data_and_parameter = {}, data, trace,\ntrace_type, type_list = [], label_list = [], trace_value_dict, dataset_list =\n[], dataset, i, j, layout, title; if (configuration_dict.constructor ===\nString) { configuration_dict = JSON.parse(configuration_dict); } data =\nconfiguration_dict.data || []; layout = configuration_dict.layout || {}; title\n= layout.title; // title // The position of the title in plotly was fixed, like\nthe \"x:center\" in echarts. // For now, every graph have to provide a title. if\n(title === undefined) { throw new Error(\"No title provided\", data); }\ngraph_data_and_parameter.title = { text: title, x: \"center\" }; // tooltip //\nECharts have to enable the tooltip manually. graph_data_and_parameter.tooltip =\n{}; graph_data_and_parameter.tooltip.trigger = \"item\"; // legend // Initialize\nthe legend. graph_data_and_parameter.legend = {};\ngraph_data_and_parameter.legend.y = 25; graph_data_and_parameter.legend.data =\n[]; // Axis // Initialize the axis graph_data_and_parameter.xAxis = [];\ngraph_data_and_parameter.yAxis = []; for (i = 0; i < data.length; i = i + 1) {\ntrace = data[i]; trace_type = trace.type || \"bar\"; type_list.push(trace_type);\ntrace_value_dict = trace.value_dict || {}; if ( trace_value_dict[0] ===\nundefined || trace_value_dict[1] === undefined ) { throw new Error(\"Unexpected\ndata for ECharts\", data); } dataset = {}; dataset.type = trace_type;\ndataset.name = trace.title || {}; // If the graph type is pie, set the pie\nradius // plotly doesn\'t have this option. if (trace_type === \"pie\") {\ndataset.radius = \"55%\"; dataset.center = [\"50%\", \"60%\"]; } // For pie graph,\nthe legend labels come from each item\'s title(aka trace.title) // For graph\nwhich contains the axis, the legend labels come from the item\'s value_dict[0].\n// See the trace_value_dict in below. But the duplicated value_dict[0] seems\nfor 2D graph // seems is redandunt. if (trace.type !== \"pie\") {\ngraph_data_and_parameter.legend.data.push(dataset.name); } dataset.data = [];\nfor (j = 0; j < trace_value_dict[0].length; j = j + 1) { if (label_list.length\n!== trace_value_dict[0].length) { label_list[j] = trace_value_dict[0][j]; } } /\n/ Value for (j = 0; j < trace_value_dict[1].length; j = j + 1) {\ndataset.data.push({ value: trace_value_dict[1][j], name: label_list[j],\nitemStyle: null }); // Handle the colors in different ways. Maybe enhanced\nlatter if (trace.colors) { // In the pie graph, set the color each individual\n\"data\" item. if (trace.type === \"pie\") { dataset.data[j].itemStyle = { normal:\n{ color: trace.colors[j] } }; } else { // In other types of graph, set the\ncolor for each group. dataset.itemStyle = { normal: { color: trace.colors[0] }\n}; } } } dataset_list.push(dataset); } // For the pie graph, the legend label\nis the value_dict[0] if (trace.type === \"pie\") {\ngraph_data_and_parameter.legend.data = label_list; } // Axis if (trace.type !==\n\"pie\") { // if not value type provided, set it as \"value\".\ngraph_data_and_parameter.yAxis.push({ type: \"value\", name: layout.axis_dict\n[1].title }); graph_data_and_parameter.xAxis.push({ data: label_list, name:\nlayout.axis_dict[0].title }); } else { graph_data_and_parameter.xAxis = null;\ngraph_data_and_parameter.yAxis = null; } graph_data_and_parameter.series =\ndataset_list; return graph_data_and_parameter; }; /////////////////////////////\n//////////////////////////////////// // some methods //////////////////////////\n/////////////////////////////////////// gadget_klass .declareAcquiredMethod\n(\"chartItemClick\", \"chartItemClick\") //////////////////////////////////////////\n/////////////////////// // ready //////////////////////////////////////////////\n/////////////////// ///////////////////////////////////////////////////////////\n////// // published methods ///////////////////////////////////////////////////\n////////////// ////////////////////////////////////////////////////////////////\n/ // acquired methods /////////////////////////////////////////////////////////\n//////// ///////////////////////////////////////////////////////////////// //\ndeclared methods //////////////////////////////////////////////////////////////\n/// .declareMethod(\"render\", function (option_dict) { var gadget = this; //\ndelegate rendering to onStateChange to avoid redrawing the graph //every time\nrender is called (a form might call render every time //some other fields needs\nupdate) gadget.changeState({ value: option_dict.value }); }) .onStateChange\n(function (modification_dict) { var gadget = this, graph_data_and_parameter,\nchart; // the gadget is ready when both the graph is rendered and the click\nhandler is attached. if ( modification_dict.hasOwnProperty(\"clickHandlerReady\")\n|| modification_dict.hasOwnProperty(\"chartRendered\") ) { if\n(gadget.state.clickHandlerReady && gadget.state.chartRendered) {\ngadget.element.querySelector(\".graph-content\").removeAttribute(\"disabled\"); }\nelse { gadget.element.querySelector(\".graph-content\").setAttribute(\"disabled\");\n} } if (modification_dict.hasOwnProperty(\"value\")) { chart =\necharts.getInstanceByDom( gadget.element.querySelector(\".graph-content\") );\ngraph_data_and_parameter = getGraphDataAndParameterFromConfiguration(\nmodification_dict.value ); chart.on(\"finished\", function onFinished() {\ngadget.changeState({ chartRendered: true }); chart.off(\"finish\", onFinished);\n}); chart.setOption(graph_data_and_paramet