; if\n(configuration_dict.constructor === String) { configuration_dict = JSON.parse\n(configuration_dict); } layout = configuration_dict.layout || {}; data =\nconfiguration_dict.data || []; axis_dict = layout.axis_dict || {}; x_label =\n(axis_dict[0] || {}).title; y_label = (axis_dict[1] || {}).title; if (x_label !\n== undefined) { graph_data_and_parameter.xlabel = x_label; } if (y_label !==\nundefined) { graph_data_and_parameter.ylabel = y_label; } label_list.push\n(x_label); /* Dygraph only support 2D, so we assume we have only only two axis\nfor data. Then for now we only support series having same x, it can be enhanced\nlater.*/ /* We assume below that the x axis for all data is the same.\nOtherwise, dygraph needs that we fill empty values by hand, which is not done\nhere yet When having several series, we can set mapping to [y1, y2, y3, etc].\nThough dygraph expect having exactly y, y2, y3, etc]. So we have to remap. */\ngraph_data_and_parameter.series = {}; function setSerie(value) { var\nserie_value_index; var mapped_serie; serie = {}; serie_value_list.push(value);\nserie_value_index = serie_value_list.indexOf(value); if (serie_value_index ===\n0) { mapped_serie = \"y\"; } else { mapped_serie = \"y\" + (serie_value_index + 1);\n} serie.axis = mapped_serie; serie_value_mapping[value] = mapped_serie; if\n(type === \"scatter\") { serie.drawPoints = true; serie.strokeWidth = 0; }\nconsole.log(\"serie\", serie); graph_data_and_parameter.series[trace.title || \'\']\n= serie; } for (i = 0; i < data.length; i = i + 1) { trace = data[i];\ntrace_value_dict = trace.value_dict || {}; label_list.push(trace.title || \'\');\nif (trace_value_dict[0] === undefined || trace_value_dict[1] === undefined) {\nthrow new Error(\"Unexpected data for dygraph\", data); } if (dygraph_data.length\n=== 0) { // Initialize x axis for (j = 0; j < trace_value_dict[0].length; j = j\n+ 1) { // When used within iframe, we have to recreate date object since the\ndate is now string dygraph_data[j] = [new Date(trace_value_dict[0][j])]; } }\ntype = trace.type || \'line\'; // to fill y axis for trace for (j = 0; j <\ntrace_value_dict[1].length; j = j + 1) { dygraph_data[j].push(trace_value_dict\n[1][j]); } axis_mapping_id_dict = trace.axis_mapping_id_dict || {};\nObject.values(axis_mapping_id_dict).forEach(setSerie); } /* Define parameters\nof axes */ graph_data_and_parameter.axes = {}; object_key_list = Object.keys\n(axis_dict); Object.entries(axis_dict).forEach(function (axis_data) { var\naxis_id = axis_data[0], axis_configuration = axis_data[1]; if\n(serie_value_mapping[axis_id] !== undefined) { axis_id = serie_value_mapping\n[axis_id]; } graph_data_and_parameter.axes[axis_id] = {}; if\n(axis_configuration.position !== undefined) { graph_data_and_parameter.axes\n[axis_id].position = axis_configuration.position; graph_data_and_parameter.axes\n[axis_id].independentTicks = true; // XXX Needed ??? } }); if\n(graph_data_and_parameter.axes[0] !== undefined) {\ngraph_data_and_parameter.axes.x = graph_data_and_parameter.axes[0];\ngraph_data_and_parameter.axes.x.title = \"date\"; // XXX FIX delete\ngraph_data_and_parameter.axes[0]; } graph_data_and_parameter.labels =\nlabel_list; graph_data_and_parameter.dygraph_data = dygraph_data;\ngraph_data_and_parameter.dygraph_parameter_dict = graph_data_and_parameter;\nreturn graph_data_and_parameter; }; ///////////////////////////////////////////\n////////////////////// // some methods ////////////////////////////////////////\n///////////////////////// gadget_klass ////////////////////////////////////////\n///////////////////////// // ready ////////////////////////////////////////////\n///////////////////// .ready(function (gadget) { gadget.property_dict = {}; })\n///////////////////////////////////////////////////////////////// // published\nmethods ///////////////////////////////////////////////////////////////// /////\n//////////////////////////////////////////////////////////// // acquired\nmethods ///////////////////////