//////////////\n///////////////////////////// // Acquired methods /////////////////////////////\n//////////////////////////////////// .declareAcquiredMethod\n(\"jio_getAttachment\", \"jio_getAttachment\") .declareAcquiredMethod\n(\"jio_putAttachment\", \"jio_putAttachment\") .declareAcquiredMethod\n(\"jio_allDocs\", \"jio_allDocs\") .declareAcquiredMethod(\"jio_put\", \"jio_put\")\n.declareAcquiredMethod(\"jio_get\", \"jio_get\") .declareAcquiredMethod\n(\"getSetting\", \"getSetting\") //////////////////////////////////////////////////\n/////////////// // declared methods ///////////////////////////////////////////\n////////////////////// .declareMethod(\"convertFromOperation\", function (id) {\nvar gadget = this; return gadget.jio_get(id) .push(function (doc) { return\ngadget.convert(doc) .push(function () { doc.status = \"converted\"; return\ngadget.jio_put(id, doc); }, function (error) { if (error instanceof\njIO.util.jIOError) { doc.status = \"error\"; doc.error = jIO.util.stringify\n(error); return gadget.jio_put(id, doc); } throw error; }); }); })\n.declareMethod(\"convert\", function (options) { var gadget = this, jio_gadget;\nreturn gadget.getDeclaredGadget(\"jio\") .push(function (sub_gadget) { jio_gadget\n= sub_gadget; return RSVP.all([ gadget.jio_getAttachment(options.id,\noptions.name), jio_gadget.put(options.id, {from: options.from, to: options.to})\n]); }) .push(function (result) { return jio_gadget.putAttachment(options.id,\noptions.name, result[0]); }) .push(function () { return\njio_gadget.getAttachment(options.id, options.name); }) .push(function\n(converted_blob) { return gadget.jio_putAttachment( options.id, options.to_name\n|| options.to, converted_blob ); }); }) .declareMethod(\'repair\', function () {\nvar gadget = this; function convertAndPush(rows, i) { if (i === -1) { return\nnew RSVP.Queue(); } return convertAndPush(rows, i - 1) .push(function () {\nreturn gadget.convertFromOperation(rows[i].id); }); } return fixAllDocument\n(gadget) .push