INSERT INTO `full_text` VALUES (14303,'RenderJS Gadget OfficeJS CSS gadget_officejs_nojqm.css 001 /********************************************** * Colors\n**********************************************/ /\n********************************************** * Fonts (font-family)\n**********************************************/ /\n********************************************** * Shared\n**********************************************/ /\n********************************************** * http://meyerweb.com/eric/tools\n/css/reset/ * v2.0 | 20110126 * License: none (public domain)\n**********************************************/ html, body, div, span, applet,\nobject, iframe, h1, h2, h3, h4, h5, h6, p, blockquote, pre, a, abbr, acronym,\naddress, big, cite, code, del, dfn, em, img, ins, kbd, q, s, samp, small,\nstrike, strong, sub, sup, tt, var, b, u, i, center, dl, dt, dd, ol, ul, li,\nfieldset, form, label, legend, table, caption, tbody, tfoot, thead, tr, th, td,\narticle, aside, canvas, details, embed, figure, figcaption, footer, header,\nhgroup, menu, nav, output, ruby, section, summary, time, mark, audio, video {\nmargin: 0; padding: 0; border: 0; font-size: 100%; font: inherit;\nvertical-align: baseline; } /* HTML5 display-role reset for older browsers */\narticle, aside, details, figcaption, figure, footer, header, hgroup, menu, nav,\nsection { display: block; } body { line-height: 1; } ol, ul { list-style: none;\n} blockquote, q { quotes: none; } blockquote:before, blockquote:after,\nq:before, q:after { content: \'\'; content: none; } table { border-collapse:\ncollapse; border-spacing: 0; } /**********************************************\n* Default **********************************************/ @font-face {\nfont-family: \'FontAwesome\'; src: url(\'font-awesome/font-awesome-webfont.eot\');\nsrc: url(\'font-awesome/font-awesome-webfont.eot\') format(\'embedded-opentype\'),\nurl(\'font-awesome/font-awesome-webfont.woff2\') format(\'woff2\'), url\n(\'font-awesome/font-awesome-webfont.woff\') format(\'woff\'), url(\'font-awesome/\nfont-awesome-webfont.ttf\') format(\'truetype\'), url(\'font-awesome/\nfont-awesome-webfont.svg\') format(\'svg\'); font-weight: normal; font-style:\nnormal; } html { height: 100%; width: 100%; display: block; background-color: #\nFFFFFF; box-sizing: border-box; } *, *:before, *:after { box-sizing: inherit; }\nbody { height: 100%; width: 100%; display: block; color: #1F1F1F; word-wrap:\nbreak-word; } body, button, input, textarea, select { font-family: \'Open Sans\',\nHelvetica, Arial, sans-serif; font-size: 12pt; padding: 0; margin: 0;\nfont-weight: 400; line-height: 1.5; } /\n********************************************** * Inline elements\n**********************************************/ strong { font-weight: bold; }\ni, cite, em, var, address, dfn { font-style: italic; } strong, b { font-weight:\nbold; } u, ins { text-decoration: underline; } s, strike, del {\ntext-decoration: line-through; } sup { vertical-align: super; font-size:\nsmaller; } sub { vertical-align: sub; font-size: smaller; } small { font-size:\nsmaller; } tt, code, kbd, samp { font-family: \"Courier New\", Courier,\nmonospace; } q { display: inline; quotes: initial; } q:before { content:\nopen-quote; } q:after { content: close-quote; } mark { color: #22CC22; } /\n********************************************** * Link\n**********************************************/ a { color: #2FA2E4;\ntext-decoration: none; } a[href=\"\"] { color: #1F1F1F; } a:hover {\ntext-decoration: underline; } a:focus { outline-offset: -2px; outline: 2px\nsolid #3388cc; } @media not screen and (max-width: 2713em) { a[accesskey]:after\n{ content: \" [\" attr(accesskey) \"] \"; } } /\n********************************************** * Preformatted\n**********************************************/ pre, xmp, plaintext, listing {\ndisplay: block; white-space: pre-wrap; } /\n********************************************** * hr\n*********************************************